diff --git a/golang/architecture/proofdischarge/compatibility.go b/golang/architecture/proofdischarge/compatibility.go
new file mode 100644
index 00000000..ccf1bb07
--- /dev/null
+++ b/golang/architecture/proofdischarge/compatibility.go
@@ -0,0 +1,243 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import (
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/globulario/sensei/golang/architecture/binding"
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+)
+
+// CheckCompatibility reports whether a single validated receipt may discharge a
+// single slot, and — when it may not — a machine-readable reason. Checks run
+// most-fundamental first and short-circuit on the first failure so the outcome
+// is deterministic. It assumes the receipt already passed Phase-4 validation and
+// the Step-0.5 re-validation; it does not re-validate structural shape here.
+//
+// The predicate is the compatibility gate the brief describes: same result /
+// shared proof context, correct evidence kind, governed observation path,
+// correct authority domain, correct runtime target, current freshness, adequate
+// trust, no unresolved conflict, and no revocation.
+func CheckCompatibility(
+	ob ProofObligation,
+	slot ProofSlotSpec,
+	receipt closureprotocol.EvidenceReceipt,
+	profile closureprotocol.EvidenceProfile,
+	ctx Context,
+) (ok bool, reasons []string) {
+	fail := func(code string) (bool, []string) { return false, []string{code} }
+
+	// 1. Revocation.
+	if ctx.RevokedReceiptIDs[strings.TrimSpace(receipt.ReceiptID)] {
+		return fail(ReasonReceiptRevoked)
+	}
+
+	// 2. Evidence kind admitted by the slot kind (rejects `authority` kind too).
+	if !evidenceKindAllowed(slot.Kind, receipt.EvidenceKind) {
+		return fail(ReasonEvidenceKindMismatch)
+	}
+
+	// 3. Governing profile must be known and identify the receipt.
+	if strings.TrimSpace(profile.ProfileID) == "" ||
+		strings.TrimSpace(profile.ProfileID) != strings.TrimSpace(receipt.ProfileID) {
+		return fail(ReasonProfileUnknown)
+	}
+
+	// 4. Observation path must be the profile's legal (owner) path — no
+	//    arbitrary shell / broadened invocation.
+	if !observationPathSatisfies(profile.LegalObservationPath, receipt.ObservationPath) {
+		return fail(ReasonObservationPathUngoverned)
+	}
+
+	// 5. Same result / shared proof context.
+	if !binding.ResultBindingEqual(receipt.ResultBinding, ctx.ResultBinding) {
+		return fail(ReasonResultBindingMismatch)
+	}
+
+	// 6. Authority domain: a pinned profile target must intersect the
+	//    obligation's authority surfaces.
+	if !authorityDomainMatches(ob, profile) {
+		return fail(ReasonAuthorityDomainMismatch)
+	}
+
+	// 7. Runtime target: runtime evidence must come from the target under proof.
+	if code, okRT := checkRuntimeTarget(receipt, ctx); !okRT {
+		return fail(code)
+	}
+
+	// 8. Trust must be attested.
+	if !trustAttested(receipt.Trust) {
+		return fail(ReasonTrustInsufficient)
+	}
+
+	// 9. Freshness: an explicit expiry at or before ObservedAt is stale.
+	if code, okF := checkFreshness(receipt, ctx.ObservedAt); !okF {
+		return fail(code)
+	}
+
+	// 10. No unresolved conflict with another live receipt.
+	if hasUnresolvedConflict(receipt, ctx) {
+		return fail(ReasonConflictUnresolved)
+	}
+
+	return true, nil
+}
+
+// observationPathSatisfies mirrors the owner-path rule the Phase-4 validator
+// uses: the legal path may be namespaced as "<mechanism>.<path>"; a receipt path
+// equal to the full string, to a trailing segment, or extending it is accepted.
+// An empty legal or actual path never satisfies an owner-only profile.
+func observationPathSatisfies(legal, actual string) bool {
+	legal = strings.TrimSpace(legal)
+	actual = strings.TrimSpace(actual)
+	if legal == "" || actual == "" {
+		return false
+	}
+	if legal == actual {
+		return true
+	}
+	if strings.HasSuffix(legal, "."+actual) {
+		return true
+	}
+	if strings.HasPrefix(actual, legal+".") {
+		return true
+	}
+	return false
+}
+
+// authorityDomainMatches returns true unless the obligation pins authority
+// surfaces and the profile pins a governed target that is not among them.
+func authorityDomainMatches(ob ProofObligation, profile closureprotocol.EvidenceProfile) bool {
+	target := strings.TrimSpace(profile.GovernedTarget)
+	if target == "" || len(ob.AppliesToAuthoritySurfaces) == 0 {
+		return true
+	}
+	for _, s := range ob.AppliesToAuthoritySurfaces {
+		if strings.TrimSpace(s) == target {
+			return true
+		}
+	}
+	return false
+}
+
+// checkRuntimeTarget compares a runtime-bearing receipt's target against the one
+// under proof. Non-runtime receipts, and runs with no pinned runtime target, are
+// not gated here.
+func checkRuntimeTarget(receipt closureprotocol.EvidenceReceipt, ctx Context) (string, bool) {
+	if ctx.RuntimeTarget == nil {
+		return "", true
+	}
+	if receipt.EvidenceKind != closureprotocol.EvidenceRuntime && receipt.RuntimeTarget == nil {
+		return "", true
+	}
+	if !runtimeTargetEqual(receipt.RuntimeTarget, ctx.RuntimeTarget) {
+		return ReasonRuntimeTargetMismatch, false
+	}
+	return "", true
+}
+
+func runtimeTargetEqual(a, b *closureprotocol.RuntimeTarget) bool {
+	if a == nil || b == nil {
+		return a == b
+	}
+	return strings.TrimSpace(a.Platform) == strings.TrimSpace(b.Platform) &&
+		strings.TrimSpace(a.EnvironmentID) == strings.TrimSpace(b.EnvironmentID) &&
+		strings.TrimSpace(a.DeploymentID) == strings.TrimSpace(b.DeploymentID) &&
+		strings.TrimSpace(a.ReleaseRevision) == strings.TrimSpace(b.ReleaseRevision) &&
+		strings.TrimSpace(a.ConfigurationGeneration) == strings.TrimSpace(b.ConfigurationGeneration) &&
+		stringSetEqual(a.NodeIDs, b.NodeIDs) &&
+		stringSetEqual(a.ServiceInstances, b.ServiceInstances)
+}
+
+func trustAttested(trust string) bool {
+	t := strings.TrimSpace(trust)
+	return t != "" && t != TrustUnattested
+}
+
+// checkFreshness treats an explicit expiry at or before ObservedAt as stale,
+// regardless of the receipt's self-declared status (an upstream staleness sweep
+// may not have run yet). ObservedAt is the deterministic evaluation time.
+func checkFreshness(receipt closureprotocol.EvidenceReceipt, observedAt string) (string, bool) {
+	expires := strings.TrimSpace(receipt.ExpiresAt)
+	if expires == "" {
+		return "", true
+	}
+	exp, err := time.Parse(time.RFC3339, expires)
+	if err != nil {
+		return ReasonFreshnessExpired, false
+	}
+	now, err := time.Parse(time.RFC3339, strings.TrimSpace(observedAt))
+	if err != nil {
+		// Caller guarantees ObservedAt is valid (Step 0); fail closed anyway.
+		return ReasonFreshnessExpired, false
+	}
+	if !exp.After(now) {
+		return ReasonFreshnessExpired, false
+	}
+	return "", true
+}
+
+// hasUnresolvedConflict reports whether the receipt is in a conflict with
+// another receipt in the context that is still live (not superseded, invalid,
+// revoked, or in the revocation index). Conflicts are read from either side's
+// Conflicts list.
+func hasUnresolvedConflict(receipt closureprotocol.EvidenceReceipt, ctx Context) bool {
+	id := strings.TrimSpace(receipt.ReceiptID)
+	for _, other := range ctx.Receipts {
+		oid := strings.TrimSpace(other.ReceiptID)
+		if oid == "" || oid == id {
+			continue
+		}
+		if !conflictReferenced(receipt, other) {
+			continue
+		}
+		if receiptLive(other, ctx) {
+			return true
+		}
+	}
+	return false
+}
+
+func conflictReferenced(a, b closureprotocol.EvidenceReceipt) bool {
+	for _, c := range a.Conflicts {
+		if strings.TrimSpace(c) == strings.TrimSpace(b.ReceiptID) {
+			return true
+		}
+	}
+	for _, c := range b.Conflicts {
+		if strings.TrimSpace(c) == strings.TrimSpace(a.ReceiptID) {
+			return true
+		}
+	}
+	return false
+}
+
+func receiptLive(r closureprotocol.EvidenceReceipt, ctx Context) bool {
+	if ctx.RevokedReceiptIDs[strings.TrimSpace(r.ReceiptID)] {
+		return false
+	}
+	switch r.Status {
+	case closureprotocol.ReceiptSuperseded, closureprotocol.ReceiptInvalid, closureprotocol.ReceiptRevoked:
+		return false
+	}
+	return true
+}
+
+func stringSetEqual(a, b []string) bool {
+	as := closureprotocol.NormalizeSet(a)
+	bs := closureprotocol.NormalizeSet(b)
+	if len(as) != len(bs) {
+		return false
+	}
+	sort.Strings(as)
+	sort.Strings(bs)
+	for i := range as {
+		if as[i] != bs[i] {
+			return false
+		}
+	}
+	return true
+}
diff --git a/golang/architecture/proofdischarge/compatibility_test.go b/golang/architecture/proofdischarge/compatibility_test.go
new file mode 100644
index 00000000..6010cb62
--- /dev/null
+++ b/golang/architecture/proofdischarge/compatibility_test.go
@@ -0,0 +1,181 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import (
+	"testing"
+
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+)
+
+// baseResult is the result binding under proof, shared by fixtures.
+func baseResult() closureprotocol.ResultBinding {
+	return closureprotocol.ResultBinding{
+		BaseRevision:           "rev1",
+		PatchDigestSHA256:      "patch1",
+		ResultTreeDigestSHA256: "tree1",
+		GraphDigestSHA256:      "graph1",
+	}
+}
+
+// okProfile is a governed profile whose legal observation path a passing receipt
+// must match exactly.
+func okProfile(id, kind string) closureprotocol.EvidenceProfile {
+	return closureprotocol.EvidenceProfile{
+		ProfileID:            id,
+		Owner:                "owner.core",
+		LegalObservationPath: "test_runner.go_test::TestFoo",
+		EvidenceKind:         closureprotocol.EvidenceKind(kind),
+		Status:               closureprotocol.ReceiptValid,
+	}
+}
+
+// okReceipt is a receipt that satisfies every compatibility check by default.
+func okReceipt(id, profileID, kind string) closureprotocol.EvidenceReceipt {
+	return closureprotocol.EvidenceReceipt{
+		ReceiptID:           id,
+		EvidenceKind:        closureprotocol.EvidenceKind(kind),
+		ProfileID:           profileID,
+		ResultBinding:       baseResult(),
+		Producer:            "producer.core",
+		ObservationPath:     "test_runner.go_test::TestFoo",
+		ObservedAt:          "2026-07-15T10:00:00Z",
+		Status:              closureprotocol.ReceiptValid,
+		Trust:               "attested",
+		PayloadDigestSHA256: "payload-" + id,
+	}
+}
+
+const observedNow = "2026-07-15T12:00:00Z"
+
+func testCtx(profiles map[string]closureprotocol.EvidenceProfile, receipts []closureprotocol.EvidenceReceipt) Context {
+	return Context{
+		ResultBinding:   baseResult(),
+		CoverageProfile: CoverageStaticTest,
+		Profiles:        profiles,
+		Receipts:        receipts,
+		ObservedAt:      observedNow,
+	}
+}
+
+func testSlot(id, kind string) ProofSlotSpec { return ProofSlotSpec{ID: id, Kind: kind, Required: true} }
+
+func testOb(id string, slots ...ProofSlotSpec) ProofObligation {
+	return ProofObligation{ID: id, Status: "candidate", RequiredSlots: slots}
+}
+
+// TestCheckCompatibility exercises one failure mode per compatibility check.
+func TestCheckCompatibility(t *testing.T) {
+	prof := okProfile("prof.test", string(closureprotocol.EvidenceTest))
+	profiles := map[string]closureprotocol.EvidenceProfile{prof.ProfileID: prof}
+	slot := testSlot("slot.a", SlotKindTestOrRuntime)
+	ob := testOb("ob.a", slot)
+
+	tests := []struct {
+		name    string
+		mutate  func(r *closureprotocol.EvidenceReceipt, c *Context)
+		wantOK  bool
+		wantOne string
+	}{
+		{name: "clean receipt passes", mutate: func(r *closureprotocol.EvidenceReceipt, c *Context) {}, wantOK: true},
+		{
+			name:    "revoked",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { c.RevokedReceiptIDs = map[string]bool{r.ReceiptID: true} },
+			wantOne: ReasonReceiptRevoked,
+		},
+		{
+			name:    "evidence kind mismatch",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { r.EvidenceKind = closureprotocol.EvidenceStatic },
+			wantOne: ReasonEvidenceKindMismatch,
+		},
+		{
+			name:    "authority kind never discharges",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { r.EvidenceKind = closureprotocol.EvidenceAuthority },
+			wantOne: ReasonEvidenceKindMismatch,
+		},
+		{
+			name: "profile unknown",
+			mutate: func(r *closureprotocol.EvidenceReceipt, c *Context) {
+				r.ProfileID = "prof.missing"
+				c.Profiles = map[string]closureprotocol.EvidenceProfile{}
+			},
+			wantOne: ReasonProfileUnknown,
+		},
+		{
+			name:    "observation path ungoverned",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { r.ObservationPath = "bash -c 'go test ./...'" },
+			wantOne: ReasonObservationPathUngoverned,
+		},
+		{
+			name:    "result binding mismatch",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { r.ResultBinding.ResultTreeDigestSHA256 = "other-tree" },
+			wantOne: ReasonResultBindingMismatch,
+		},
+		{
+			name:    "trust insufficient",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { r.Trust = TrustUnattested },
+			wantOne: ReasonTrustInsufficient,
+		},
+		{
+			name:    "freshness expired",
+			mutate:  func(r *closureprotocol.EvidenceReceipt, c *Context) { r.ExpiresAt = "2026-07-15T11:00:00Z" },
+			wantOne: ReasonFreshnessExpired,
+		},
+	}
+
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			r := okReceipt("receipt.a", prof.ProfileID, string(closureprotocol.EvidenceTest))
+			ctx := testCtx(profiles, nil)
+			tc.mutate(&r, &ctx)
+			ctx.Receipts = []closureprotocol.EvidenceReceipt{r}
+			p := ctx.Profiles[r.ProfileID]
+			ok, reasons := CheckCompatibility(ob, slot, r, p, ctx)
+			if ok != tc.wantOK {
+				t.Fatalf("ok = %v, want %v (reasons=%v)", ok, tc.wantOK, reasons)
+			}
+			if !tc.wantOK {
+				if len(reasons) == 0 || reasons[0] != tc.wantOne {
+					t.Fatalf("reasons = %v, want %q", reasons, tc.wantOne)
+				}
+			}
+		})
+	}
+}
+
+func TestAllowedEvidenceKinds(t *testing.T) {
+	if evidenceKindAllowed(SlotKindRuntime, closureprotocol.EvidenceStatic) {
+		t.Fatal("static must not be allowed for runtime slot")
+	}
+	if !evidenceKindAllowed(SlotKindRuntime, closureprotocol.EvidenceRuntime) {
+		t.Fatal("runtime must be allowed for runtime slot")
+	}
+	if !evidenceKindAllowed(SlotKindFailureEvidence, closureprotocol.EvidenceHybrid) {
+		t.Fatal("hybrid must be allowed for failure_evidence")
+	}
+	if evidenceKindAllowed(SlotKindStaticGuard, closureprotocol.EvidenceAuthority) {
+		t.Fatal("authority must never be allowed")
+	}
+}
+
+func TestResolveSlotDisposition(t *testing.T) {
+	ob := testOb("ob.x")
+	if got := ResolveSlotDisposition(ob, ProofSlotSpec{Kind: SlotKindRuntime, Required: true}, CoverageStaticTest); got != SlotNotApplicableUnderProfile {
+		t.Fatalf("runtime slot under static_test = %v, want not_applicable", got)
+	}
+	if got := ResolveSlotDisposition(ob, ProofSlotSpec{Kind: SlotKindRuntime, Required: true}, CoverageStaticTestRuntime); got != SlotRequired {
+		t.Fatalf("runtime slot under static_test_runtime = %v, want required", got)
+	}
+	// Governed mandate overrides the default profile: runtime slot stays required
+	// even under static_test.
+	mandated := ProofObligation{ID: "ob.m", RequiresRuntimeEvidence: true}
+	if got := ResolveSlotDisposition(mandated, ProofSlotSpec{Kind: SlotKindRuntime, Required: true}, CoverageStaticTest); got != SlotRequired {
+		t.Fatalf("mandated runtime slot under static_test = %v, want required (not relaxed)", got)
+	}
+	if got := ResolveSlotDisposition(ob, ProofSlotSpec{Kind: SlotKindTestOrRuntime, Required: true}, CoverageStaticTest); got != SlotRequired {
+		t.Fatalf("test_or_runtime slot = %v, want required (never relaxed)", got)
+	}
+	if got := ResolveSlotDisposition(ob, ProofSlotSpec{Kind: SlotKindStaticGuard, Required: false}, CoverageStaticTest); got != SlotOptional {
+		t.Fatalf("non-required slot = %v, want optional", got)
+	}
+}
diff --git a/golang/architecture/proofdischarge/coverage.go b/golang/architecture/proofdischarge/coverage.go
new file mode 100644
index 00000000..fae1a977
--- /dev/null
+++ b/golang/architecture/proofdischarge/coverage.go
@@ -0,0 +1,88 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import "github.com/globulario/sensei/golang/architecture/closureprotocol"
+
+// SlotDisposition is the coverage-profile decision for one slot. It is a pure
+// function of (slot.Kind, slot.Required, coverageProfile) and is NEVER
+// conditioned on whether evidence happens to exist for the slot.
+type SlotDisposition int
+
+const (
+	SlotRequired SlotDisposition = iota
+	SlotNotApplicableUnderProfile
+	SlotOptional
+)
+
+// ResolveSlotDisposition decides, before any receipt is considered, whether a
+// slot must be discharged, is optional, or is not applicable under the coverage
+// profile. The decision is obligation-driven, not merely repository-driven.
+//
+// The coverage profile sets the DEFAULT disposition only for runtime-owner-path
+// slots whose runtime requirement is NOT mandated by the obligation. When a
+// governed obligation MANDATES runtime evidence (ob.RequiresRuntimeEvidence),
+// its runtime-owner-path slots stay required regardless of profile — including
+// under static_test — so a missing compatible runtime receipt yields a
+// blocked/uncertifiable obligation, NEVER not_applicable. A runtime lane is
+// not_applicable only when no applicable required proof slot needs runtime
+// evidence AND the profile permits relaxation; it is required when a governed
+// obligation requires it OR the claim cannot be established statically or by
+// test. Static/test-satisfiable kinds are never relaxed.
+func ResolveSlotDisposition(ob ProofObligation, slot ProofSlotSpec, coverageProfile string) SlotDisposition {
+	if !slot.Required {
+		return SlotOptional
+	}
+	if !isRuntimeOwnerPathKind(slot.Kind) {
+		return SlotRequired
+	}
+	// Runtime-owner-path kind:
+	if ob.RequiresRuntimeEvidence {
+		return SlotRequired // governed mandate overrides the profile, incl. static_test
+	}
+	if coverageProfile == CoverageStaticTestRuntime {
+		return SlotRequired
+	}
+	// static_test (default), not mandated: profile-relaxable.
+	return SlotNotApplicableUnderProfile
+}
+
+func isRuntimeOwnerPathKind(kind string) bool {
+	for _, k := range RuntimeOwnerPathSlotKinds {
+		if k == kind {
+			return true
+		}
+	}
+	return false
+}
+
+// AllowedEvidenceKinds returns the evidence_kinds a slot kind will accept as
+// candidates. A receipt whose evidence_kind is not in this set is filtered out
+// before the compatibility predicate ever runs. `authority`-kind receipts back
+// AuthorityResolution, not ProofDischarge, and are in no set.
+func AllowedEvidenceKinds(slotKind string) []closureprotocol.EvidenceKind {
+	switch slotKind {
+	case SlotKindStaticGuard, SlotKindScopeMapping, SlotKindBeforeAfter,
+		SlotKindArtifact, SlotKindInputValidation, SlotKindNegativeContract:
+		return []closureprotocol.EvidenceKind{closureprotocol.EvidenceStatic, closureprotocol.EvidenceArtifact}
+	case SlotKindProcessArtifact, SlotKindLogArtifact:
+		return []closureprotocol.EvidenceKind{closureprotocol.EvidenceArtifact, closureprotocol.EvidenceRuntime}
+	case SlotKindTestOrRuntime:
+		return []closureprotocol.EvidenceKind{closureprotocol.EvidenceTest, closureprotocol.EvidenceRuntime}
+	case SlotKindRuntime:
+		return []closureprotocol.EvidenceKind{closureprotocol.EvidenceRuntime}
+	case SlotKindFailureEvidence:
+		return []closureprotocol.EvidenceKind{closureprotocol.EvidenceRuntime, closureprotocol.EvidenceTest, closureprotocol.EvidenceHybrid}
+	default:
+		return nil
+	}
+}
+
+func evidenceKindAllowed(slotKind string, kind closureprotocol.EvidenceKind) bool {
+	for _, k := range AllowedEvidenceKinds(slotKind) {
+		if k == kind {
+			return true
+		}
+	}
+	return false
+}
diff --git a/golang/architecture/proofdischarge/digest.go b/golang/architecture/proofdischarge/digest.go
new file mode 100644
index 00000000..6c551213
--- /dev/null
+++ b/golang/architecture/proofdischarge/digest.go
@@ -0,0 +1,21 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import "github.com/globulario/sensei/golang/architecture/closureprotocol"
+
+// WithDigest sets discharge_digest_sha256 via the frozen
+// closureprotocol.ProofDischargeDigest (computed over the canonical form with the
+// digest field cleared) and re-validates the result. It is a thin wrapper — the
+// canonicalization and digest live in closureprotocol, not here.
+func WithDigest(d closureprotocol.ProofDischarge) (closureprotocol.ProofDischarge, error) {
+	digest, err := closureprotocol.ProofDischargeDigest(d)
+	if err != nil {
+		return closureprotocol.ProofDischarge{}, err
+	}
+	d.DischargeDigestSHA256 = digest
+	if err := closureprotocol.ValidateProofDischarge(d); err != nil {
+		return closureprotocol.ProofDischarge{}, err
+	}
+	return d, nil
+}
diff --git a/golang/architecture/proofdischarge/discharge.go b/golang/architecture/proofdischarge/discharge.go
new file mode 100644
index 00000000..b06b9bae
--- /dev/null
+++ b/golang/architecture/proofdischarge/discharge.go
@@ -0,0 +1,254 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import (
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/globulario/sensei/golang/architecture/binding"
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+)
+
+// Discharge maps validated evidence receipts to the proof slots of each
+// obligation and emits, per obligation, a schema-conformant
+// closureprotocol.ProofDischarge plus a diagnostic DischargeReport. It is
+// deterministic: identical input produces byte-identical output (including
+// digests). Discharge never reads the wall clock — ctx.ObservedAt is the single
+// evaluation time for every freshness/expiry comparison.
+func Discharge(ctx Context) ([]closureprotocol.ProofDischarge, DischargeReport, error) {
+	report := DischargeReport{
+		SchemaVersion: SchemaVersion,
+		GeneratedBy:   GeneratedBy,
+	}
+
+	// Step 0 — context validation (fail-closed).
+	if err := binding.ValidateResult(ctx.ResultBinding); err != nil {
+		return nil, report, err
+	}
+	profile := normalizeCoverageProfile(ctx.CoverageProfile)
+	ctx.CoverageProfile = profile
+	report.CoverageProfile = profile
+
+	if profile == CoverageStaticTestRuntime && ctx.RuntimeTarget == nil && anyRequiredRuntimeSlot(ctx.Obligations) {
+		return nil, report, ErrRuntimeTargetMissing
+	}
+	if _, err := time.Parse(time.RFC3339, strings.TrimSpace(ctx.ObservedAt)); err != nil {
+		return nil, report, ErrObservedAtInvalid
+	}
+
+	// Step 0.5 — defensive re-validation. Receipts that fail are dropped
+	// entirely (never a slot candidate) and logged only on the report.
+	usable := make([]closureprotocol.EvidenceReceipt, 0, len(ctx.Receipts))
+	for _, r := range ctx.Receipts {
+		if reValidate(r, ctx.Profiles) {
+			usable = append(usable, r)
+		} else {
+			report.DroppedReceipts = append(report.DroppedReceipts, ReceiptEvaluation{
+				ReceiptID:   strings.TrimSpace(r.ReceiptID),
+				Compatible:  false,
+				ReasonCodes: []string{ReasonReinvalidationFailed},
+			})
+		}
+	}
+	ctx.Receipts = usable // conflict detection must only consult surviving receipts
+
+	// Step 1 — normalize for determinism.
+	sort.SliceStable(usable, func(i, j int) bool {
+		return strings.TrimSpace(usable[i].ReceiptID) < strings.TrimSpace(usable[j].ReceiptID)
+	})
+	obligations := append([]ProofObligation(nil), ctx.Obligations...)
+	sort.SliceStable(obligations, func(i, j int) bool { return obligations[i].ID < obligations[j].ID })
+
+	// Step 2 — per obligation.
+	discharges := make([]closureprotocol.ProofDischarge, 0, len(obligations))
+	for _, ob := range obligations {
+		d, obReport, err := dischargeOne(ctx, ob, usable)
+		if err != nil {
+			return nil, report, err
+		}
+		discharges = append(discharges, d)
+		report.Obligations = append(report.Obligations, obReport)
+	}
+	return discharges, report, nil
+}
+
+func dischargeOne(ctx Context, ob ProofObligation, usable []closureprotocol.EvidenceReceipt) (closureprotocol.ProofDischarge, ObligationReport, error) {
+	slots := append([]ProofSlotSpec(nil), ob.RequiredSlots...)
+	sort.SliceStable(slots, func(i, j int) bool { return slots[i].ID < slots[j].ID })
+
+	d := closureprotocol.ProofDischarge{ObligationID: ob.ID}
+	obReport := ObligationReport{ObligationID: ob.ID}
+
+	var missing []string
+	var incompatible []string // receipt ids that failed as a candidate for some slot
+	var usedReceipts []string // receipt ids that discharged some slot
+	hasConflicted, hasStale := false, false
+
+	for _, slot := range slots {
+		disposition := ResolveSlotDisposition(ob, slot, ctx.CoverageProfile)
+		slotReport := SlotReport{SlotID: slot.ID, CoverageDisposition: dispositionLabel(disposition)}
+
+		if disposition == SlotNotApplicableUnderProfile {
+			d.SlotResults = append(d.SlotResults, closureprotocol.ProofSlotResult{
+				SlotID: slot.ID, Status: closureprotocol.DimensionNotApplicable,
+			})
+			obReport.Slots = append(obReport.Slots, slotReport)
+			continue
+		}
+
+		var passing []string
+		var failReasons []string
+		for _, r := range usable {
+			if !evidenceKindAllowed(slot.Kind, r.EvidenceKind) {
+				continue // not a candidate; not "incompatible"
+			}
+			prof := ctx.Profiles[strings.TrimSpace(r.ProfileID)]
+			ok, reasons := CheckCompatibility(ob, slot, r, prof, ctx)
+			slotReport.Candidates = append(slotReport.Candidates, ReceiptEvaluation{
+				ReceiptID:   strings.TrimSpace(r.ReceiptID),
+				Compatible:  ok,
+				ReasonCodes: reasons,
+			})
+			if ok {
+				passing = append(passing, strings.TrimSpace(r.ReceiptID))
+			} else {
+				incompatible = append(incompatible, strings.TrimSpace(r.ReceiptID))
+				failReasons = append(failReasons, reasons...)
+			}
+		}
+
+		if len(passing) > 0 {
+			ids := closureprotocol.NormalizeSet(passing)
+			d.SlotResults = append(d.SlotResults, closureprotocol.ProofSlotResult{
+				SlotID: slot.ID, Status: closureprotocol.DimensionPass, ReceiptIDs: ids,
+			})
+			usedReceipts = append(usedReceipts, ids...)
+			obReport.Slots = append(obReport.Slots, slotReport)
+			continue
+		}
+
+		// Zero passing receipts.
+		if disposition == SlotOptional {
+			d.SlotResults = append(d.SlotResults, closureprotocol.ProofSlotResult{
+				SlotID: slot.ID, Status: closureprotocol.DimensionUnknown,
+			})
+			obReport.Slots = append(obReport.Slots, slotReport)
+			continue
+		}
+
+		// Required slot with no passing receipt: try a governed waiver.
+		if waiverID, ok := ResolveWaiver(ob, slot, ctx); ok {
+			// The frozen ValidateProofDischarge requires >=1 receipt id for a
+			// pass/pass_with_exception slot, so the authorizing WaiverReceipt id
+			// is recorded here (the frozen ProofSlotResult has no waiver field).
+			d.SlotResults = append(d.SlotResults, closureprotocol.ProofSlotResult{
+				SlotID: slot.ID, Status: closureprotocol.DimensionPassWithException,
+				ReceiptIDs: []string{waiverID},
+			})
+			usedReceipts = append(usedReceipts, waiverID)
+			slotReport.WaiverApplied = waiverID
+			obReport.Slots = append(obReport.Slots, slotReport)
+			continue
+		}
+
+		// No waiver: the slot is unsatisfied. Classify by the dominant failure.
+		status := closureprotocol.DimensionBlocked
+		switch {
+		case containsReason(failReasons, ReasonConflictUnresolved):
+			status = closureprotocol.DimensionConflicted
+			hasConflicted = true
+		case containsReason(failReasons, ReasonFreshnessExpired):
+			status = closureprotocol.DimensionStale
+			hasStale = true
+		}
+		d.SlotResults = append(d.SlotResults, closureprotocol.ProofSlotResult{
+			SlotID: slot.ID, Status: status,
+		})
+		missing = append(missing, slot.ID)
+		obReport.Slots = append(obReport.Slots, slotReport)
+	}
+
+	// Obligation-level aggregation.
+	d.MissingSlots = closureprotocol.NormalizeSet(missing)
+	d.MappedEvidence = closureprotocol.NormalizeSet(usedReceipts)
+	usedSet := map[string]bool{}
+	for _, id := range usedReceipts {
+		usedSet[id] = true
+	}
+	var incompatibleFiltered []string
+	for _, id := range incompatible {
+		if !usedSet[id] {
+			incompatibleFiltered = append(incompatibleFiltered, id)
+		}
+	}
+	d.IncompatibleReceipts = closureprotocol.NormalizeSet(incompatibleFiltered)
+
+	// Obligation-level status (a receipt_status). blocked/unknown have no
+	// receipt_status analog; both collapse to invalid here.
+	switch {
+	case len(d.MissingSlots) == 0 && !hasConflicted && !hasStale:
+		d.Status = closureprotocol.ReceiptValid
+	case hasConflicted:
+		d.Status = closureprotocol.ReceiptConflicted
+	case hasStale:
+		d.Status = closureprotocol.ReceiptStale
+	default:
+		d.Status = closureprotocol.ReceiptInvalid
+	}
+
+	// Steps 17-18 — self-check and digest (WithDigest re-validates).
+	withDigest, err := WithDigest(d)
+	if err != nil {
+		return closureprotocol.ProofDischarge{}, ObligationReport{}, err
+	}
+	return withDigest, obReport, nil
+}
+
+func normalizeCoverageProfile(s string) string {
+	switch strings.TrimSpace(s) {
+	case CoverageStaticTestRuntime:
+		return CoverageStaticTestRuntime
+	default:
+		return CoverageStaticTest
+	}
+}
+
+func anyRequiredRuntimeSlot(obligations []ProofObligation) bool {
+	for _, ob := range obligations {
+		for _, slot := range ob.RequiredSlots {
+			if slot.Required && isRuntimeOwnerPathKind(slot.Kind) {
+				return true
+			}
+		}
+	}
+	return false
+}
+
+// reValidate re-runs the Phase-4 structural validators and requires the receipt
+// to still carry a valid status (Phase 4 marks staleness/conflict/revocation on
+// the status). A receipt failing any of these is dropped from consideration.
+func reValidate(r closureprotocol.EvidenceReceipt, profiles map[string]closureprotocol.EvidenceProfile) bool {
+	if closureprotocol.ValidateEvidenceReceipt(r) != nil {
+		return false
+	}
+	if r.Status != closureprotocol.ReceiptValid {
+		return false
+	}
+	if prof, ok := profiles[strings.TrimSpace(r.ProfileID)]; ok {
+		if closureprotocol.ValidateEvidenceReceiptAgainstProfile(prof, r) != nil {
+			return false
+		}
+	}
+	return true
+}
+
+func containsReason(reasons []string, want string) bool {
+	for _, r := range reasons {
+		if r == want {
+			return true
+		}
+	}
+	return false
+}
