+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import (
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+	"gopkg.in/yaml.v3"
+)
+
+// TestFixtureProofDischarges cross-checks that the proof_discharge records the
+// shared closure fixtures carry are valid under the frozen validator this engine
+// targets — the same pattern closureprotocol/fixtures_test.go uses. Bundles that
+// carry no proof_discharge are skipped.
+func TestFixtureProofDischarges(t *testing.T) {
+	root := filepath.Join("..", "..", "..", "docs", "fixtures", "architectural-closure", "v1")
+	paths := []string{
+		"completed/bundle.yaml",
+		"migration-in-progress/bundle.yaml",
+	}
+	for _, rel := range paths {
+		t.Run(rel, func(t *testing.T) {
+			data, err := os.ReadFile(filepath.Join(root, rel))
+			if err != nil {
+				t.Fatal(err)
+			}
+			var env struct {
+				Fixture struct {
+					Records struct {
+						ProofDischarge *closureprotocol.ProofDischarge `yaml:"proof_discharge"`
+					} `yaml:"records"`
+				} `yaml:"closure_protocol_fixture"`
+			}
+			if err := yaml.Unmarshal(data, &env); err != nil {
+				t.Fatal(err)
+			}
+			pd := env.Fixture.Records.ProofDischarge
+			if pd == nil {
+				t.Skip("no proof_discharge in bundle")
+			}
+			if err := closureprotocol.ValidateProofDischarge(*pd); err != nil {
+				t.Fatalf("frozen validator rejected fixture proof_discharge: %v", err)
+			}
+		})
+	}
+}
diff --git a/golang/architecture/proofdischarge/model.go b/golang/architecture/proofdischarge/model.go
new file mode 100644
index 00000000..a4a68742
--- /dev/null
+++ b/golang/architecture/proofdischarge/model.go
@@ -0,0 +1,170 @@
+// SPDX-License-Identifier: Apache-2.0
+
+// Package proofdischarge implements Phase 5 (proof execution & discharge) of the
+// architectural closure protocol. It maps Phase-4-validated evidence receipts to
+// the proof slots of a governed proof obligation and emits, per obligation, a
+// schema-conformant closureprotocol.ProofDischarge plus a diagnostic
+// DischargeReport carrying the per-receipt reason codes the frozen schema has no
+// room for.
+//
+// This package does NOT redefine any frozen closure-protocol type. ProofDischarge,
+// ProofSlotResult, their validator (ValidateProofDischarge) and digest
+// (ProofDischargeDigest) all live in golang/architecture/closureprotocol and are
+// imported and reused here — mirroring how the Phase-4 evidencereceipt package
+// aliases the frozen primitives.
+//
+// Determinism is a hard requirement: the engine never reads the wall clock (the
+// caller supplies ObservedAt) and never iterates a map without a subsequent sort.
+package proofdischarge
+
+import (
+	"os"
+
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+	"github.com/globulario/sensei/golang/architecture/probe"
+	"gopkg.in/yaml.v3"
+)
+
+const (
+	SchemaVersion = "1"
+	GeneratedBy   = "sensei discharge-proofs"
+
+	CoverageStaticTest        = "static_test"         // default
+	CoverageStaticTestRuntime = "static_test_runtime" // opt-in
+
+	// Slot-kind vocabulary. Copied from
+	// docs/awareness/generated/proof_obligations.yaml required_slots[].kind and
+	// from probe's ProofSlotKinds groupings. proofdischarge invents no new kinds.
+	SlotKindStaticGuard      = "static_guard"
+	SlotKindScopeMapping     = "scope_mapping"
+	SlotKindBeforeAfter      = "before_after"
+	SlotKindArtifact         = "artifact"
+	SlotKindInputValidation  = "input_validation"
+	SlotKindNegativeContract = "negative_contract"
+	SlotKindTestOrRuntime    = "test_or_runtime"
+	SlotKindRuntime          = "runtime"
+	SlotKindProcessArtifact  = "process_artifact"
+	SlotKindLogArtifact      = "log_artifact"
+	SlotKindFailureEvidence  = "failure_evidence"
+)
+
+// RuntimeOwnerPathSlotKinds are the slot kinds that can only be satisfied by a
+// live runtime observation of the owning service — exactly the four kinds the
+// `service_lifecycle` proof-obligation template emits. coverage.go downgrades
+// these to not_applicable under the default (static_test) profile.
+var RuntimeOwnerPathSlotKinds = []string{
+	SlotKindRuntime, SlotKindProcessArtifact, SlotKindLogArtifact, SlotKindFailureEvidence,
+}
+
+// ProofObligation is the engine's read model of one governed proof obligation,
+// produced by LoadFromYAML / LoadFromGraph so the engine never touches RDF or
+// extractor internals directly.
+type ProofObligation struct {
+	ID                          string          `json:"id" yaml:"id"`
+	Status                      string          `json:"status" yaml:"status"` // candidate|approved authored lifecycle status; not a receipt_status
+	DerivedFromAuthoritySurface string          `json:"derived_from_authority_surface,omitempty" yaml:"derived_from_authority_surface,omitempty"`
+	AppliesToAuthoritySurfaces  []string        `json:"applies_to_authority_surfaces,omitempty" yaml:"applies_to_authority_surfaces,omitempty"`
+	EvidenceLane                string          `json:"evidence_lane,omitempty" yaml:"evidence_lane,omitempty"`
+	// RequiresRuntimeEvidence is the governed-mandate signal: when true, this
+	// obligation MANDATES runtime evidence, so its runtime-owner-path slots stay
+	// required regardless of coverage profile (including under static_test) and
+	// can never be silently relaxed to not_applicable. Default false leaves such
+	// slots profile-relaxable (the coverage profile alone decides). This exists
+	// because a claim that cannot be established statically or by test — leader
+	// election, durability, failover, consistency — must not be rubber-stamped by
+	// the default profile.
+	RequiresRuntimeEvidence bool            `json:"requires_runtime_evidence,omitempty" yaml:"requires_runtime_evidence,omitempty"`
+	RequiredSlots           []ProofSlotSpec `json:"required_slots" yaml:"required_slots"`
+}
+
+type ProofSlotSpec struct {
+	ID          string `json:"id" yaml:"id"`
+	Kind        string `json:"kind" yaml:"kind"`
+	Description string `json:"description,omitempty" yaml:"description,omitempty"`
+	Required    bool   `json:"required" yaml:"required"` // authored flag; the coverage profile may still relax it to not_applicable
+}
+
+// Context is everything Discharge needs. Every collection is expected
+// pre-validated by its own package (closureprotocol validators / Phase-4
+// evidencereceipt). Discharge re-checks defensively (fail-closed) but does not
+// attempt to repair invalid input.
+type Context struct {
+	Obligations   []ProofObligation
+	ResultBinding closureprotocol.ResultBinding // the exact result being proved
+	Task          closureprotocol.TaskBinding
+
+	CoverageProfile string                         // CoverageStaticTest (default) | CoverageStaticTestRuntime
+	RuntimeTarget   *closureprotocol.RuntimeTarget // required only under static_test_runtime when an obligation has a runtime-owner-path required slot
+
+	Profiles map[string]closureprotocol.EvidenceProfile // profile_id -> profile, Phase-4-validated
+	Receipts []closureprotocol.EvidenceReceipt          // Phase-4-validated receipts
+
+	Waivers              []closureprotocol.WaiverReceipt
+	GovernanceExceptions map[string]GovernanceException // keyed by WaiverReceipt.PolicyID
+
+	RevokedReceiptIDs map[string]bool // receipt_id -> true
+
+	ObservedAt string // RFC3339, the deterministic "now" for every freshness/expiry comparison
+}
+
+// BuildRevokedSet reduces a list of revocation receipts to the receipt-id set
+// Discharge consumes. Phase 5 provides this helper so a caller that only has raw
+// RevocationReceipts does not have to reimplement the reduction.
+func BuildRevokedSet(revocations []closureprotocol.RevocationReceipt) map[string]bool {
+	out := make(map[string]bool, len(revocations))
+	for _, r := range revocations {
+		if id := r.RevokedTargetID; id != "" {
+			out[id] = true
+		}
+	}
+	return out
+}
+
+// LoadFromYAML loads proof obligations from the authored YAML shape emitted by
+// `sensei extract-proof-obligations` (docs/awareness/generated/proof_obligations.yaml).
+func LoadFromYAML(path string) ([]ProofObligation, error) {
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return nil, err
+	}
+	var doc struct {
+		ProofObligations []ProofObligation `yaml:"proof_obligations"`
+	}
+	if err := yaml.Unmarshal(data, &doc); err != nil {
+		return nil, err
+	}
+	return doc.ProofObligations, nil
+}
+
+// LoadFromGraph is a thin adapter from the compiled graph read model: it joins
+// each proof_obligation node with its proof_slot nodes over the ProofSlots edge.
+// It does not duplicate GraphIndex's triple-walking logic.
+func LoadFromGraph(g probe.GraphIndex) ([]ProofObligation, error) {
+	var out []ProofObligation
+	for _, node := range g.Class("proof_obligation") {
+		ob := ProofObligation{
+			ID:                          node.ID,
+			Status:                      node.Status,
+			DerivedFromAuthoritySurface: node.DerivedFromAuthoritySurface,
+			AppliesToAuthoritySurfaces:  node.AppliesToAuthoritySurfaces,
+			EvidenceLane:                node.EvidenceLane,
+			// A non-empty requiresRuntimeEvidence on the obligation node is the
+			// governed mandate that its runtime-owner-path slots stay required.
+			RequiresRuntimeEvidence: len(node.RequiresRuntimeEvidence) > 0,
+		}
+		for _, slotID := range node.ProofSlots {
+			slotNode, ok := g.Node("proof_slot", slotID)
+			if !ok {
+				continue
+			}
+			ob.RequiredSlots = append(ob.RequiredSlots, ProofSlotSpec{
+				ID:          slotNode.ID,
+				Kind:        slotNode.SlotKind,
+				Description: slotNode.Comment,
+				Required:    slotNode.Required,
+			})
+		}
+		out = append(out, ob)
+	}
+	return out, nil
+}
diff --git a/golang/architecture/proofdischarge/report.go b/golang/architecture/proofdischarge/report.go
new file mode 100644
index 00000000..4fe0a632
--- /dev/null
+++ b/golang/architecture/proofdischarge/report.go
@@ -0,0 +1,59 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+// DischargeReport is the non-authoritative, non-schema diagnostic companion to a
+// []closureprotocol.ProofDischarge result. It exists solely because the frozen
+// schema has no field for per-slot / per-receipt reasoning. Nothing in Phase 6
+// (certification) may read this report as authoritative — only
+// ProofDischarge.Status / SlotResults[].Status / DischargeDigestSHA256 are
+// authoritative. This mirrors probe.GenerationReport / probe.RecordingReport.
+type DischargeReport struct {
+	SchemaVersion   string             `json:"schema_version" yaml:"schema_version"`
+	GeneratedBy     string             `json:"generated_by" yaml:"generated_by"`
+	CoverageProfile string             `json:"coverage_profile" yaml:"coverage_profile"`
+	Obligations     []ObligationReport `json:"obligations" yaml:"obligations"`
+	// DroppedReceipts records receipts dropped at Step 0.5 (re-validation
+	// failure) before they could become a candidate for any slot. They are not
+	// eligible for any ProofDischarge.incompatible_receipts field.
+	DroppedReceipts []ReceiptEvaluation `json:"dropped_receipts,omitempty" yaml:"dropped_receipts,omitempty"`
+}
+
+type ObligationReport struct {
+	ObligationID string       `json:"obligation_id" yaml:"obligation_id"`
+	Slots        []SlotReport `json:"slots" yaml:"slots"`
+}
+
+type SlotReport struct {
+	SlotID              string              `json:"slot_id" yaml:"slot_id"`
+	CoverageDisposition string              `json:"coverage_disposition" yaml:"coverage_disposition"` // "required" | "not_applicable_under_profile" | "optional"
+	Candidates          []ReceiptEvaluation `json:"candidates,omitempty" yaml:"candidates,omitempty"`
+	WaiverApplied       string              `json:"waiver_applied,omitempty" yaml:"waiver_applied,omitempty"` // waiver_id, diagnostic only
+}
+
+// ReceiptEvaluation records, for one receipt considered against one slot, whether
+// it passed the compatibility predicate and why not if it failed. ReasonCodes is
+// the "compatibility_reasons" content the frozen schema has no room for.
+type ReceiptEvaluation struct {
+	ReceiptID   string   `json:"receipt_id" yaml:"receipt_id"`
+	Compatible  bool     `json:"compatible" yaml:"compatible"`
+	ReasonCodes []string `json:"reason_codes,omitempty" yaml:"reason_codes,omitempty"`
+}
+
+// Coverage-disposition strings recorded in SlotReport.CoverageDisposition.
+const (
+	DispositionRequired      = "required"
+	DispositionNotApplicable = "not_applicable_under_profile"
+	DispositionOptional      = "optional"
+)
+
+func dispositionLabel(d SlotDisposition) string {
+	switch d {
+	case SlotNotApplicableUnderProfile:
+		return DispositionNotApplicable
+	case SlotOptional:
+		return DispositionOptional
+	default:
+		return DispositionRequired
+	}
+}
diff --git a/golang/architecture/proofdischarge/waiver.go b/golang/architecture/proofdischarge/waiver.go
new file mode 100644
index 00000000..095412c2
--- /dev/null
+++ b/golang/architecture/proofdischarge/waiver.go
@@ -0,0 +1,101 @@
+// SPDX-License-Identifier: Apache-2.0
+
+package proofdischarge
+
+import (
+	"strings"
+	"time"
+
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+)
+
+// GovernanceException is Phase 5's minimal read model of the ontology class
+// GovernanceException. No frozen JSON Schema file defines this record in this
+// snapshot; this shape is proposed here (keyed by WaiverReceipt.PolicyID, the
+// only foreign key available on the frozen WaiverReceipt) and MUST be reconciled
+// with whatever schema a later phase freezes for it. A governance exception is
+// the governance ceiling; a waiver is the concrete, narrower grant under it.
+type GovernanceException struct {
+	ID                     string   `json:"id" yaml:"id"`
+	Status                 string   `json:"status" yaml:"status"`    // must be "governed" to authorize a waiver
+	Dimension              string   `json:"dimension" yaml:"dimension"` // must equal "proof"
+	AppliesToObligationIDs []string `json:"applies_to_obligation_ids,omitempty" yaml:"applies_to_obligation_ids,omitempty"`
+	AppliesToSlotIDs       []string `json:"applies_to_slot_ids,omitempty" yaml:"applies_to_slot_ids,omitempty"`
+	ExpiresAt              string   `json:"expires_at,omitempty" yaml:"expires_at,omitempty"`
+}
+
+const governanceExceptionGoverned = "governed"
+
+// ResolveWaiver reports whether a governed exception justifies skipping a
+// missing required slot. ALL conditions must hold, in order, short-circuiting on
+// the first failure. A CLI flag, free-text note, environment variable, or
+// unvalidated struct literal is never a waiver: only a typed WaiverReceipt that
+// independently validates AND resolves through a governed GovernanceException at
+// the exact slot granularity satisfies a slot.
+func ResolveWaiver(ob ProofObligation, slot ProofSlotSpec, ctx Context) (waiverID string, ok bool) {
+	now, err := time.Parse(time.RFC3339, strings.TrimSpace(ctx.ObservedAt))
+	if err != nil {
+		return "", false
+	}
+	for _, w := range ctx.Waivers {
+		// 0. The waiver must independently be a valid, schema-conformant record.
+		if closureprotocol.ValidateWaiverReceipt(w) != nil {
+			continue
+		}
+		// 1. proof dimension, valid status.
+		if w.Dimension != closureprotocol.DimensionProof || w.Status != closureprotocol.ReceiptValid {
+			continue
+		}
+		// 2. Not expired relative to the deterministic now.
+		exp, err := time.Parse(time.RFC3339, strings.TrimSpace(w.ExpiresAt))
+		if err != nil || !exp.After(now) {
+			continue
+		}
+		// 3. Scoped to exactly this slot (never obligation-wide blanket).
+		if !containsExact(w.AppliesTo, slot.ID) {
+			continue
+		}
+		// 4. Resolves to a governed governance exception keyed by PolicyID.
+		ge, found := ctx.GovernanceExceptions[strings.TrimSpace(w.PolicyID)]
+		if !found || ge.Status != governanceExceptionGoverned {
+			continue
+		}
+		// 5. Exception is a proof exception.
+		if ge.Dimension != string(closureprotocol.DimensionProof) {
+			continue
+		}
+		// 6. Exception covers this slot (slot granularity) or, when it lists no
+		//    slots, this obligation (obligation granularity ceiling).
+		if !exceptionCoversSlot(ge, ob, slot) {
+			continue
+		}
+		// 7. Exception not itself expired.
+		if e := strings.TrimSpace(ge.ExpiresAt); e != "" {
+			ee, err := time.Parse(time.RFC3339, e)
+			if err != nil || !ee.After(now) {
+				continue
+			}
+		}
+		return w.WaiverID, true
+	}
+	return "", false
+}
+
+func exceptionCoversSlot(ge GovernanceException, ob ProofObligation, slot ProofSlotSpec) bool {
+	if containsExact(ge.AppliesToSlotIDs, slot.ID) {
+		return true
+	}
+	if len(ge.AppliesToSlotIDs) == 0 && containsExact(ge.AppliesToObligationIDs, ob.ID) {
+		return true
+	}
+	return false
+}
+
+func containsExact(list []string, want string) bool {
+	for _, v := range list {
+		if strings.TrimSpace(v) == strings.TrimSpace(want) {
+			return true
+		}
+	}
+	return false
+}
